#include <stdio.h>
#include <stdlib.h>
int cmp_int(const void *a, const void *b)
{
    return *(int*)a - *(int*)b;   /* 升序；想降序就反过来b-a */
}
int main()
{
    int arr[5] = {5, 2, 9, 1, 7};
    qsort(arr, 5, sizeof(int), cmp_int);
    for (int i = 0; i < 5; i++)
        printf("%d ", arr[i]);   /* 1 2 5 7 9 */
    return 0;
}

int cmp_double(const void *a, const void *b)
{
    double x = *(double*)a, y = *(double*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;   /* double不能直接相减（精度坑）！ */
}

