#include <stdio.h>
void bubbleSort(int a[], int n)
{
    for (int i = 0; i < n - 1; i++)      /* 共n-1轮 */
    {
        int swapped = 0;                 /* 优化：记录本轮是否交换 */
        for (int j = 0; j < n - 1 - i; j++)  /* 每轮少比一个 */
        {
            if (a[j] > a[j + 1])         /* 前面比后面大就交换 */
            {
                int t = a[j]; a[j] = a[j+1]; a[j+1] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;             /* 没交换=已排好，提前结束 */
    }
}
int main()
{
    int a[5] = {5, 2, 9, 1, 7};
    bubbleSort(a, 5);
    for (int i = 0; i < 5; i++) printf("%d ", a[i]);  /* 1 2 5 7 9 */
    return 0;
}

void selectSort(int a[], int n)
{
    for (int i = 0; i < n - 1; i++)
    {
        int min = i;                       /* 先假设第i个最小 */
        for (int j = i + 1; j < n; j++)
            if (a[j] < a[min]) min = j;    /* 发现更小的记下标 */
        if (min != i)                      /* 最小的不是自己才交换 */
        {
            int t = a[i]; a[i] = a[min]; a[min] = t;
        }
    }
}

void insertSort(int a[], int n)
{
    for (int i = 1; i < n; i++)      /* 从第2个开始 */
    {
        int key = a[i];              /* 摸一张新牌 */
        int j = i - 1;
        while (j >= 0 && a[j] > key) /* 前面比新牌大的往后挪 */
        {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;              /* 新牌插入空位 */
    }
}

void quickSort(int a[], int left, int right)
{
    if (left >= right) return;        /* 递归出口：0或1个数 */
    int i = left, j = right;
    int pivot = a[left];              /* 取第一个做基准 */
    while (i < j)
    {
        while (i < j && a[j] >= pivot) j--;  /* 从右找小的 */
        a[i] = a[j];
        while (i < j && a[i] <= pivot) i++;  /* 从左找大的 */
        a[j] = a[i];
    }
    a[i] = pivot;                     /* 基准归位 */
    quickSort(a, left, i - 1);        /* 递归左半 */
    quickSort(a, i + 1, right);       /* 递归右半 */
}
/* 调用：quickSort(arr, 0, n-1); */

void merge(int a[], int tmp[], int left, int mid, int right)
{
    int i = left, j = mid + 1, k = left;
    while (i <= mid && j <= right)          /* 双指针取小者 */
        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= mid)  tmp[k++] = a[i++];   /* 剩余直接搬 */
    while (j <= right) tmp[k++] = a[j++];
    for (i = left; i <= right; i++) a[i] = tmp[i];
}
void mergeSort(int a[], int tmp[], int left, int right)
{
    if (left >= right) return;
    int mid = (left + right) / 2;
    mergeSort(a, tmp, left, mid);
    mergeSort(a, tmp, mid + 1, right);
    merge(a, tmp, left, mid, right);
}

int seqSearch(int a[], int n, int key)
{
    for (int i = 0; i < n; i++)
        if (a[i] == key)
            return i;      /* 找到返回下标 */
    return -1;             /* 没找到 */
}

int binSearch(int a[], int n, int key)
{
    int left = 0, right = n - 1;
    while (left <= right)              /* 注意是<= */
    {
        int mid = left + (right - left) / 2;  /* 防溢出写法 */
        if (a[mid] == key) return mid;
        else if (a[mid] < key) left = mid + 1;   /* 去右半 */
        else right = mid - 1;                    /* 去左半 */
    }
    return -1;
}

