} Stack;
void init(Stack *s) { s->top = -1; }
int isEmpty(Stack *s) { return s->top == -1; }
int isFull(Stack *s) { return s->top == SIZE - 1; }
void push(Stack *s, int x)
{
    if (isFull(s)) { printf("栈满\n"); return; }
    s->data[++s->top] = x;
}
int pop(Stack *s)
{
    if (isEmpty(s)) { printf("栈空\n"); return -1; }
    return s->data[s->top--];
}
